'use strict';
const L=(et,en)=>lang==='et'?et:en;
ui.et.pastMapP='Algse projekti kureeritud 2021–2025 laia matemaatika teemaviited.';
ui.en.pastMapP='Curated 2021–2025 broad-mathematics topic references from the original project.';
const now=()=>Date.now();
// Clear rendered maths before replacing its DOM, keeping repeated study navigation light.
const htmlDescriptor=Object.getOwnPropertyDescriptor(Element.prototype,'innerHTML');
Object.defineProperty(content,'innerHTML',{get(){return htmlDescriptor.get.call(this)},set(value){window.MathJax?.typesetClear?.([this]);htmlDescriptor.set.call(this,value)}});

const TOPICS=Object.entries(DB.modules).flatMap(([mk,m])=>Object.entries(m.topics).map(([tk,tp])=>({mk,tk,path:mk+'/'+tk,m,tp})));
const QUESTIONS=TOPICS.flatMap(r=>(r.tp.questions||[]).map((q,i)=>({...r,q,id:r.path+'/p/'+i,index:i})));
const FORMULAS=TOPICS.flatMap(r=>(r.tp.formulas||[]).map((f,i)=>({...r,f,id:r.path+'/f/'+i,index:i})));
const questionMap=new Map(QUESTIONS.map(r=>[r.id,r])),formulaMap=new Map(FORMULAS.map(r=>[r.id,r]));
const validKeys=new Set([...questionMap.keys(),...formulaMap.keys()]);
const freshState=()=>({version:2,ratings:{},drafts:{},notes:{},saved:[],confidence:{},goal:5,last:'',session:null});
let storageOK=true;
function validateState(input){
  if(!input||typeof input!=='object'||input.version!==2)throw Error('Invalid backup version');
  const s=freshState();
  for(const field of ['drafts','notes']){const data=input[field];if(data&&typeof data==='object'&&!Array.isArray(data))for(const [id,value] of Object.entries(data)){if((validKeys.has(id)||TOPICS.some(r=>r.path===id))&&typeof value==='string')s[field][id]=value.slice(0,20000)}}
  if(input.ratings&&typeof input.ratings==='object')for(const [id,r] of Object.entries(input.ratings)){if(!validKeys.has(id)||!r||!['again','hard','good'].includes(r.grade))continue;const n=Number(r.count),due=Number(r.due),at=Number(r.at);if(!Number.isFinite(n)||n<1||n>1e6||!Number.isFinite(due)||!Number.isFinite(at))continue;s.ratings[id]={grade:r.grade,count:Math.floor(n),due,at,good:Math.max(0,Math.min(n,Number(r.good)||0))}}
  s.saved=Array.isArray(input.saved)?[...new Set(input.saved.filter(id=>validKeys.has(id)))]:[];
  for(const r of TOPICS){const c=input.confidence?.[r.path];if(['new','learning','confident'].includes(c))s.confidence[r.path]=c}
  s.goal=[3,5,10].includes(input.goal)?input.goal:5;
  if(typeof input.last==='string'&&(TOPICS.some(r=>input.last.startsWith(r.path+'/'))||['library','curriculum','cards','practice','notebook','lab','glossary'].includes(input.last)))s.last=input.last;
  const session=input.session;if(session&&Array.isArray(session.ids)&&session.ids.length<=50&&session.ids.every(id=>questionMap.has(id))&&['mixed','weak','timed'].includes(session.mode)){
    const index=Number(session.index);if(Number.isInteger(index)&&index>=0&&index<=session.ids.length){s.session={ids:[...new Set(session.ids)],index,mode:session.mode,started:Number(session.started)||now(),deadline:Number(session.deadline)||0,finished:!!session.finished,assessed:{}};for(const [id,g] of Object.entries(session.assessed||{}))if(s.session.ids.includes(id)&&['again','hard','good'].includes(g))s.session.assessed[id]=g;s.session.index=Math.min(s.session.index,s.session.ids.length)}
  }
  return s;
}
let state=(()=>{try{const raw=localStorage.getItem('pm_study_v2');return raw?validateState(JSON.parse(raw)):freshState()}catch(e){storageOK=false;return freshState()}})();
let toastTimer;
function toast(message){const box=document.getElementById('saveStatus');box.textContent=message;box.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>box.classList.remove('visible'),4000)}
function save(){try{localStorage.setItem('pm_study_v2',JSON.stringify(state));storageOK=true;return true}catch(e){if(storageOK)toast(L('Salvestamine ei õnnestunud. Ekspordi varukoopia enne lahkumist.','Saving failed. Export a backup before leaving.'));storageOK=false;return false}}
function rate(id,grade){
  const previous=state.ratings[id]||{count:0,good:0};const count=previous.count+1;const good=previous.good+(grade==='good'?1:0);
  const days=grade==='again'?10/1440:grade==='hard'?1:Math.min(14,3*Math.max(1,good));
  state.ratings[id]={count,good,grade,at:now(),due:now()+days*86400000};save();
}
function saved(id){return state.saved.includes(id)}
function toggleSaved(id){if(!validKeys.has(id))return;state.saved=saved(id)?state.saved.filter(x=>x!==id):[...state.saved,id];save()}
function star(id){return `<button class="star ${saved(id)?'saved':''}" data-save="${esc(id)}" aria-pressed="${saved(id)}" aria-label="${L('Salvesta või eemalda','Save or unsave')}">${saved(id)?'★':'☆'}</button>`}
function gradeButtons(id,chosen=''){return `<div class="rate-row" data-rates="${esc(id)}">${[['again',L('Vajan abi','Need help')],['hard',L('Peaaegu','Almost there')],['good',L('Lahendasin ise','Solved unaided')]].map(([g,name])=>`<button class="rating ${chosen===g?'chosen':''}" data-rate="${g}" data-id="${esc(id)}">${name}</button>`).join('')}</div>`}
function bindStars(){content.querySelectorAll('[data-save]').forEach(b=>b.onclick=()=>{toggleSaved(b.dataset.save);b.classList.toggle('saved',saved(b.dataset.save));b.setAttribute('aria-pressed',saved(b.dataset.save));b.textContent=saved(b.dataset.save)?'★':'☆'})}
function bindDrafts(){content.querySelectorAll('[data-draft]').forEach(el=>el.oninput=()=>{state.drafts[el.dataset.draft]=el.value;save()});content.querySelectorAll('[data-note]').forEach(el=>el.oninput=()=>{state.notes[el.dataset.note]=el.value;save()})}
function bindRatings(callback){content.querySelectorAll('[data-rate]').forEach(b=>b.onclick=()=>{const row=b.closest('[data-rates]');if(row.dataset.rated)return;row.dataset.rated='true';rate(b.dataset.id,b.dataset.rate);row.querySelectorAll('button').forEach(x=>{x.classList.toggle('chosen',x===b);x.disabled=true});if(callback)callback(b.dataset.id,b.dataset.rate);else toast(L('Enesehinnang salvestatud.','Self-assessment saved.'))})}
function numericValue(value){const s=value.trim().replace(/−/g,'-').replace(/,/g,'.');if(/^[+-]?(?:\d+(?:\.\d*)?|\.\d+)$/.test(s))return Number(s);const m=s.match(/^([+-]?(?:\d+(?:\.\d*)?|\.\d+))\s*\/\s*([+-]?(?:\d+(?:\.\d*)?|\.\d+))$/);if(m&&Number(m[2])!==0)return Number(m[1])/Number(m[2]);return NaN}
function numericBox(r){if(r.q.numeric===undefined)return '';return `<details><summary>${L('Kontrolli ainult arvulist vastust','Check the numeric answer only')}</summary><p class="tiny">${L('See kontroll ei hinda lahenduskäiku ega sümbolavaldisi. Sisesta arv, kümnendmurd või murd (nt 1/2).','This check does not assess your working or symbolic expressions. Enter a number, decimal or fraction (e.g. 1/2).')}</p><label class="field">${L('Arvuline vastus','Numeric answer')}<input data-numeric-input="${r.id}" inputmode="decimal" autocomplete="off"></label><button class="mini" data-check="${r.id}">${L('Kontrolli','Check')}</button><p class="tiny" role="status" data-numeric-result="${r.id}"></p></details>`}
function bindNumeric(){content.querySelectorAll('[data-check]').forEach(b=>b.onclick=()=>{const r=questionMap.get(b.dataset.check);const input=content.querySelector(`[data-numeric-input="${r.id}"]`);const out=content.querySelector(`[data-numeric-result="${r.id}"]`);const v=numericValue(input.value);out.textContent=!Number.isFinite(v)?L('Sisesta arv või murd.','Enter a number or fraction.'):Math.abs(v-r.q.numeric)<=Math.max(r.q.numericTolerance||0,1e-6*Math.max(1,Math.abs(r.q.numeric)))?L('Arvuline osa sobib. Võrdle ka lahenduskäiku.','The numeric part matches. Compare your working too.'):L('Veel ei sobi. Vaata vihjet ja proovi uuesti.','Not yet. Try a hint and another attempt.')})}
function hintFor(r){return r.q.hint?t(r.q.hint):L('Pane kirja antud suurused ja otsitav. Ava selle teema valemileht; vali valem, mille suurused sobivad. Kontrolli ühikuid ja piiranguid.','List what is given and what you need. Open this topic’s formula page and choose a formula with matching quantities. Check units and restrictions.')}
function practiceCard(r,solutionOpen=false){return `<article class="question" data-qid="practice-${r.index}"><div class="q-meta"><span class="difficulty ${r.q.difficulty}">${ui[lang][r.q.difficulty]}</span><span class="tiny">${esc(t(r.tp.title))} · ${L('Originaalharjutus','Original practice')}</span>${star(r.id)}</div><p>${t(r.q.q)}</p><label class="attempt-label" for="draft-${r.id.replaceAll('/','-')}">${L('Minu katse · salvestub selles brauseris','My attempt · saved in this browser')}</label><textarea id="draft-${r.id.replaceAll('/','-')}" data-draft="${r.id}" placeholder="${L('Kirjuta sammud, mitte ainult vastus…','Write the steps, not just the answer…')}">${esc(state.drafts[r.id]||'')}</textarea><details><summary>${L('Väike vihje','A small hint')}</summary>${hintFor(r)}</details>${numericBox(r)}<button class="reveal" aria-expanded="${solutionOpen}">${ui[lang].reveal}</button><div class="answer ${solutionOpen?'show':''}"><div>${t(r.q.a)}</div><p class="tiny">${L('Võrdle oma lahendusega ja hinda, kui iseseisvalt lahendasid.','Compare with your work and assess how independently you solved it.')}</p>${gradeButtons(r.id)}<label class="attempt-label">${L('Mida järgmisel korral teisiti teen?','What will I do differently next time?')}</label><textarea data-note="${r.id}" placeholder="${L('Näiteks: kontrollin DEG/RAD režiimi.','For example: check the DEG/RAD setting.')}">${esc(state.notes[r.id]||'')}</textarea></div></article>`}
function bindPractice(){bindNav();bindStars();bindDrafts();bindRatings();bindNumeric();content.querySelectorAll('.reveal').forEach(b=>b.onclick=()=>{const box=b.nextElementSibling;box.classList.toggle('show');const opened=box.classList.contains('show');b.textContent=opened?ui[lang].hide:ui[lang].reveal;b.setAttribute('aria-expanded',opened)});typeset()}
// Fix the old search: rows with zero matching tokens must not survive on type weight alone.
const originalScoreSearch=scoreSearch;
scoreSearch=function(row,q){const tokens=queryTokens(q);if(!tokens.length||!tokens.some(token=>row.blob.includes(token)))return 0;return originalScoreSearch(row,q)};
function buildTree(){
  const nav=[['', '🏠',L('Minu õpilaud','My study desk')],['library','📚',L('Valemid ja teemad','Lessons & formulas')],['practice','✏️',L('Harjutussessioon','Practice session')],['cards','▣',L('Valemikaardid','Formula cards')],['notebook','★',L('Minu märkmik','My notebook')],['curriculum','🧭',L('Õppekava ja eksam','Curriculum & exam')],['lab','〰️',L('Graafikulabor','Graph lab')],['glossary','💬',L('ET / EN sõnastik','ET / EN glossary')],['settings','⚙️',L('Eelistused ja varukoopia','Settings & backup')]];
  tree.innerHTML=nav.map(([path,icon,name])=>`<button class="nav-item" data-go="${path}"><span>${icon}</span>${name}</button>`).join('')+`<div class="tree-title">${L('PRAEGUSED KURSUSED','CURRENT COURSES')}</div>`+Object.entries(DB.modules).filter(([mk])=>mk!=='review').map(([mk,m])=>`<button class="nav-item" data-go="${mk}"><span>${m.icon}</span>${m.code} · ${esc(t(m.title))}</button>`).join('')+`<div class="tree-title">${L('LAIEM KORDAMINE','BROADER REVISION')}</div><button class="nav-item" data-go="review"><span>🧩</span>${L('Puudunud teemade alustunnid','Starter lessons for missing topics')}</button><button class="nav-item" data-go="archive"><span>🗂️</span>${ui[lang].archive}</button>`;
  tree.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>go(b.dataset.go));highlight();
}
go=function(path){document.getElementById('sidebar').classList.remove('open');searchResults.classList.remove('show');if(routeParts().join('/')===path){render();return}location.hash='#/'+path};
function header(title,sub,tag='PURRITY MATA'){return `<div class="page-head"><div><span class="eyebrow">${tag}</span><h2>${title}</h2><p>${sub}</p></div></div>`}
function home(){
  const ratings=Object.entries(state.ratings).filter(([id])=>questionMap.has(id));const attempts=ratings.reduce((sum,[,r])=>sum+r.count,0);const due=Object.values(state.ratings).filter(r=>r.due<=now()).length;const weak=ratings.filter(([,r])=>r.grade!=='good').map(([id])=>questionMap.get(id));
  const recent=TOPICS.filter(r=>state.confidence[r.path]);const todayStart=new Date().setHours(0,0,0,0);const today=ratings.filter(([,r])=>r.at>=todayStart).length;
  content.innerHTML=`<div class="hero"><span class="eyebrow">${L('VÄIKE SAMM. SUUREM KINDLUS.','SMALL STEPS. MORE CONFIDENCE.')}</span><h2>${L('Mata, aga nurrub.','Maths, but it purrs.')}</h2><p>${L('Ei pea kõike korraga oskama. Vali üks teema, proovi ise ja jäta tulevasele endale üks hea vihje.','You don’t need to know everything at once. Pick one topic, try it yourself, and leave your future self a useful clue.')}</p><div class="actions"><button class="primary" data-go="practice">${state.session&&!state.session.finished?L('Jätka sessiooni','Resume session'):L('Alusta väikest sessiooni','Start a small session')} →</button><button class="secondary" data-go="library">${L('Sirvi teemasid','Browse lessons')}</button></div></div><div class="stats"><div class="stat"><b>${attempts}</b><span>${L('enesehinnatud katset','self-assessed attempts')}</span></div><div class="stat"><b>${due}</b><span>${L('kordamist ootab','reviews due')}</span></div><div class="stat"><b>${Math.min(today,state.goal)} / ${state.goal}</b><span>${L('tänaseid ülesandeid','questions today')}</span></div></div><div class="desk-grid"><div class="card"><span class="eyebrow">${L('MIDA EDASI ÕPPIDA?','WHAT SHOULD I STUDY NEXT?')}</span><h3 style="margin-top:10px">${weak.length?L('Siin kasvab kindlus','Your confidence grows here'):L('Alusta millestki tuttavast','Begin somewhere familiar')}</h3>${(weak.length?weak.slice(0,3):QUESTIONS.filter(r=>['combinatorics','plane','analytic'].includes(r.tk)).slice(0,3)).map(r=>`<div class="list-row"><div><span class="row-name">${esc(t(r.tp.title))}</span><small>${weak.length?L('Viimane katse vajas tuge','Last attempt needed support'):L('Proovi üks ülesanne','Try one question')}</small></div><button class="mini" data-go="${r.path}/questions/practice/${r.index}">${L('Proovi','Try')} →</button></div>`).join('')}<p class="tiny">${L('Soovitused põhinevad sinu enesehinnangul, mitte ennustatud eksamitulemusel.','Suggestions use your self-assessment, not a predicted exam score.')}</p></div><div class="card"><span class="eyebrow">${L('SINU ÕPPERADA','YOUR STUDY PATH')}</span><h3 style="margin-top:10px">${L('Üks teema korraga','One topic at a time')}</h3><p>${L('Igal teemal saad märkida oma kindlust ja kirjutada märkmeid.','Each lesson lets you set your confidence and write notes.')}</p><div class="progress-track"><div class="progress-fill" style="width:${recent.length/TOPICS.length*100}%"></div></div><p class="tiny">${recent.length} / ${TOPICS.length} ${L('teemat hinnatud','topics self-assessed')}</p><div class="actions"><button class="mini" data-go="${state.last||'library'}">${L('Tagasi viimase lehe juurde','Return to last page')} →</button><button class="mini" data-go="curriculum">${L('Vaata tervikpilti','See the bigger picture')}</button></div></div></div><div class="grid"><div class="card"><span class="tag lav">${L('MEENUTA','RECALL')}</span><h3>${L('Valem mälust, mitte ekraanilt','Recall it before revealing it')}</h3><p>${L('Valemikaardid tulevad kordamiseks tagasi sinu hinnangu järgi.','Formula cards return for review based on your rating.')}</p><div class="actions"><button class="mini" data-go="cards">${L('Ava kaardid','Open cards')} →</button></div></div><div class="card"><span class="tag mint">${L('MÕISTA','UNDERSTAND')}</span><h3>${L('Näe, mida tuletis teeb','See what a derivative does')}</h3><p>${L('Liiguta punkti paraboolil ja vaata puutujat koos valemiga.','Move a point on a parabola and connect the tangent to its formula.')}</p><div class="actions"><button class="mini" data-go="lab">${L('Ava labor','Open lab')} →</button></div></div><div class="card"><span class="tag yellow">${L('HOIA ALLES','KEEP IT')}</span><h3>${L('Märkmed, mis reisivad kaasa','Notes that travel with you')}</h3><p>${L('Salvestus on selles brauseris. Ekspordi varukoopia, et viia õppimine teise seadmesse.','Progress stays in this browser. Export a backup to move your study record to another device.')}</p><div class="actions"><button class="mini" data-go="settings">${L('Varukoopia','Backup')} →</button></div></div></div>`;bindNav();typeset();
}
function libraryPage(){content.innerHTML=header(L('Vali oma järgmine väike samm','Choose your next small step'),L('Praegused kursused ja laiem kordamine on eraldi. Kõik valemid ja ülesanded on ET / EN.','Current courses and broader revision stay separate. Formulas and practice work in ET / EN.'))+`<h3 class="section-title">${L('Praegused kursused · MA11–MA13','Current courses · MA11–MA13')}</h3><div class="grid">${Object.entries(DB.modules).filter(([mk])=>mk!=='review').map(([mk,m])=>`<div class="card"><span class="tag">${m.code}</span><h3>${m.icon} ${esc(t(m.title))}</h3><p>${esc(t(m.desc))}</p><div class="actions"><button class="mini" data-go="${mk}">${L('Vaata teemasid','See topics')} →</button></div></div>`).join('')}</div><h3 class="section-title">${L('Laiem kordamine · varem puudunud teemad','Broader revision · previously missing topics')}</h3><p class="tiny">${t(CURRICULUM.gaps)}</p><div class="topic-list">${TOPICS.filter(r=>r.mk==='review').map(r=>`<div class="card"><span class="tag lav">${L('ALUSTUND','STARTER LESSON')}</span><h3>${r.tp.icon} ${esc(t(r.tp.title))}</h3><p>${esc(t(r.tp.desc))}</p><div class="actions"><button class="mini" data-go="${r.path}">${L('Õpi','Learn')} →</button><button class="mini" data-go="${r.path}/questions">${L('Harjuta','Practise')}</button></div></div>`).join('')}</div>`;bindNav()}
const originalModulePage=modulePage;
modulePage=function(mk){originalModulePage(mk);content.querySelectorAll('.topic-actions').forEach((actions,i)=>{const tk=Object.keys(DB.modules[mk].topics)[i];const b=document.createElement('button');b.className='mini';b.textContent=L('Teema ja märkmed','Lesson & notes');b.onclick=()=>go(mk+'/'+tk);actions.prepend(b)})};
function topicPage(mk,tk){const r=TOPICS.find(x=>x.mk===mk&&x.tk===tk);const tp=r.tp;const confidence=state.confidence[r.path]||'new';crumb([ui[lang].home,r.m.code,t(tp.title)]);content.innerHTML=header(`${tp.icon} ${esc(t(tp.title))}`,esc(t(tp.desc)),r.m.code)+`<div class="page-tools"><button class="primary" data-go="${r.path}/questions">${L('Proovi ise','Try it yourself')} →</button><button class="secondary" data-go="${r.path}/formulas">${L('Valemid ja näited','Formulas & examples')}</button><button class="secondary" data-topic-session="${r.path}">${L('Väike sessioon','Small session')}</button></div>${tp.trap?`<div class="notice">${L('Levinud komistus:','Common tripwire:')} ${esc(t(tp.trap))}</div>`:''}<div class="study-panel"><h3>${L('Enne alustamist','Before you begin')}</h3><p class="tiny">${L('1. Meenuta valemit. 2. Proovi ülesannet. 3. Võrdle lahenduskäiku. 4. Märgi, mida veel harjutada.','1. Recall a formula. 2. Try a question. 3. Compare the working. 4. Note what still needs practice.')}</p>${tp.prereq?.length?`<p class="tiny">${L('Vajad tuge eelnevast?','Need an earlier stepping stone?')}</p><div class="actions">${tp.prereq.map(path=>{const r=TOPICS.find(r=>r.path===path);return r?`<button class="mini" data-go="${path}">${esc(t(r.tp.title))}</button>`:''}).join('')}</div>`:''}</div><div class="study-panel"><h3>${L('Kui kindlalt end tunned?','How confident do you feel?')}</h3><p class="tiny">${L('Sinu hinnang, mitte hinne. Seda saab igal ajal muuta.','Your assessment, not a grade. Change it any time.')}</p><div class="rate-row">${[['new',L('Uus teema','New to this')],['learning',L('Veel õpin','Still learning')],['confident',L('Tunnen end kindlalt','Feeling confident')]].map(([value,title])=>`<button class="rating ${value===confidence?'chosen':''}" data-confidence="${value}">${title}</button>`).join('')}</div><label class="attempt-label" for="topic-note">${L('Minu märkmed selle teema kohta','My notes for this topic')}</label><textarea id="topic-note" data-note="${r.path}" placeholder="${L('Mis jäi segaseks? Mida õpetajalt küsida?','What is unclear? What should I ask the teacher?')}">${esc(state.notes[r.path]||'')}</textarea></div>`;bindNav();bindDrafts();content.querySelectorAll('[data-confidence]').forEach(b=>b.onclick=()=>{state.confidence[r.path]=b.dataset.confidence;save();content.querySelectorAll('[data-confidence]').forEach(x=>x.classList.toggle('chosen',x===b))});content.querySelector('[data-topic-session]').onclick=()=>startSession('mixed',r.path,Math.min(5,tp.questions.length));typeset()}
function formulasPage(mk,tk,focus){const r=TOPICS.find(x=>x.mk===mk&&x.tk===tk);crumb([ui[lang].home,r.m.code,t(r.tp.title),ui[lang].formulas]);content.innerHTML=header(`${r.tp.icon} ${esc(t(r.tp.title))}`,L('Proovi näidet enne selle lahenduse avamist.','Try each example before opening its solution.'),L('VALEMIRAAMAT','FORMULA BOOK'))+`<div class="page-tools"><button class="mini" data-go="${r.path}">${ui[lang].back}</button><button class="mini" data-go="${r.path}/questions">${L('Harjuta seda teemat','Practise this topic')}</button></div>`+r.tp.formulas.map((f,i)=>{const id=r.path+'/f/'+i;return `<article id="formula-${i}" class="formula-card"><div class="formula-top"><div class="formula-controls"><div class="formula-title">${i+1}. ${esc(t(f.name))}</div>${star(id)}</div><div class="formula">\\[${esc(f.tex)}\\]</div><div class="formula-note">${t(f.note)}</div>${f.vars?`<div class="legend"><h5>${L('Mida tähed tähendavad','What the letters mean')}</h5><ul>${f.vars.map(v=>`<li><span class="sym">\\(${v.s}\\)</span> ${esc(v[lang])}</li>`).join('')}</ul></div>`:''}</div><div class="examples">${['e1','e2'].map((ek,idx)=>`<div class="example"><h4>${idx===0?ui[lang].direct:ui[lang].applied}</h4><p>${t(f[ek].q)}</p><details><summary>${L('Võrdle lahendust','Compare the solution')}</summary><div class="solution">${t(f[ek].a)}</div></details></div>`).join('')}</div></article>`}).join('');bindNav();bindStars();typeset();if(focus!==undefined)document.getElementById('formula-'+focus)?.scrollIntoView({block:'center'})}
function questionsPage(mk,tk,filter='all'){const r=TOPICS.find(x=>x.mk===mk&&x.tk===tk);const rows=QUESTIONS.filter(x=>x.path===r.path&&(filter==='all'||x.q.difficulty===filter));const past=pastFor(r.tp);crumb([ui[lang].home,r.m.code,t(r.tp.title),ui[lang].questions]);content.innerHTML=header(`${r.tp.icon} ${esc(t(r.tp.title))}`,L('Kirjuta oma katse, kasuta vajadusel vihjet ja võrdle alles siis vastust.','Write your attempt, use a hint if needed, then compare the answer.'),L('HARJUTAMINE','PRACTICE'))+`<div class="page-tools"><button class="mini" data-go="${r.path}">${ui[lang].back}</button><button class="mini" data-go="${r.path}/formulas">${ui[lang].formulas}</button></div><div class="q-toolbar">${['all','easy','medium','hard'].map(f=>`<button class="filter ${f===filter?'active':''}" data-filter="${f}">${ui[lang][f]}</button>`).join('')}</div>${rows.map(r=>practiceCard(r)).join('')||`<div class="empty">${L('Selle raskusastmega harjutusi veel pole. Vali „Kõik“.','No questions at this difficulty yet. Select “All”.')}</div>`}${past.length?`<h3 class="section-title">${L('Varasema eksami teemamustrid','Past-exam topic patterns')}</h3><div class="notice purple">${L('Algse projekti kureeritud viited. Need harjutused pole ametlikud eksamiülesanded; viiteid pole selles uuenduses uuesti kontrollitud.','Curated references from the original project. These exercises are not official exam questions; their references were not reverified in this update.')}</div>${past.map((q,i)=>qCard(q,i,'past-'+i)).join('')}`:''}`;content.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>questionsPage(mk,tk,b.dataset.filter));bindPractice()}
