function shuffled(rows){const result=[...rows];for(let i=result.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[result[i],result[j]]=[result[j],result[i]]}return result}
function sessionCandidates(mode,topic){let rows=QUESTIONS.filter(r=>!topic||r.path===topic);if(mode==='weak')rows=rows.filter(r=>state.ratings[r.id]&&state.ratings[r.id].grade!=='good');return shuffled(rows).sort((a,b)=>{const rank=r=>state.ratings[r.id]?.grade==='again'?0:state.ratings[r.id]?.due<=now()?1:!state.ratings[r.id]?2:3;return rank(a)-rank(b)})}
function startSession(mode,topic='',count=5){const rows=sessionCandidates(mode,topic).slice(0,count);if(!rows.length){toast(L('Veel pole nõrku teemasid. Proovi esmalt segasessiooni.','No weak items yet. Try a mixed session first.'));return}state.session={ids:rows.map(r=>r.id),index:0,mode,started:now(),deadline:mode==='timed'?now()+25*60000:0,finished:false,assessed:{}};save();go('practice')}
